async function completeGoogleNewsletterSubscription(session){if(googleNewsletterReturnHandled||new URLSearchParams(location.search).get('newsletter')!=='google'||!session?.user?.email)return;googleNewsletterReturnHandled=true;const message=$('#newsletterMessage'),t=words[language];try{await saveNewsletterEmail(session.user.email);message.textContent=t.newsletterSaved;$('.newsletter').scrollIntoView({behavior:'smooth',block:'center'});}catch(error){message.textContent=`${t.newsletterGoogleError} ${supabaseMessage(error)}`}finally{const url=new URL(location.href);url.searchParams.delete('newsletter');history.replaceState({},'',url.pathname+url.hash)}}
$('#googleNewsletterSubscribe').onclick=async buttonEvent=>{const button=buttonEvent.currentTarget,t=words[language];if(!supabaseClient){$('#newsletterMessage').textContent=t.newsletterError;return}button.disabled=true;try{const redirectTo=new URL('/?newsletter=google',location.origin).href;const {error}=await supabaseClient.auth.signInWithOAuth({provider:'google',options:{redirectTo,queryParams:{prompt:'select_account'}}});if(error)throw error}catch(error){$('#newsletterMessage').textContent=`${t.newsletterGoogleError} ${supabaseMessage(error)}`;button.disabled=false}};
function updateAccountButton(session,name='',avatarUrl=''){
  const button=$('#accountButton'),bn=language==='bn',label=String(name||session?.user?.user_metadata?.full_name||session?.user?.email?.split('@')[0]||(bn?'অ্যাকাউন্ট':'Account')).trim();
  button.classList.toggle('is-signed-in',Boolean(session));
  button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.5"/><path d="M5 20c.4-3.7 3.2-6 7-6s6.6 2.3 7 6"/></svg>';
  const photo=avatarUrl||session?.user?.user_metadata?.avatar_url;
  if(session&&photo){button.innerHTML='';const image=document.createElement('img');image.className='profile-button-avatar';image.src=window.frostlySupabaseAssetUrl?.(photo)||photo;image.alt='';button.append(image);}
  if(session){const nameNode=document.createElement('span');nameNode.className='account-name';nameNode.textContent=label;button.append(nameNode);}
  button.setAttribute('aria-label',session?(bn?`অ্যাকাউন্ট: ${label}`:`Account: ${label}`):(bn?'অ্যাকাউন্ট':'Account'));
  button.title=session?label:(bn?'অ্যাকাউন্ট':'Account');
}
