  if(!session){content.innerHTML=`<div class="orders-signin"><span class="orders-signin-icon">▤</span><h3>${t.signInForOrders}</h3><p>${t.signInForOrdersCopy}</p><button id="ordersSignInButton" class="button primary full">${t.signin}</button></div>`;$('#ordersSignInButton').onclick=()=>{setOverlay('ordersOverlay',false);setOverlay('accountOverlay',true);renderAccount();};return;}
  const {data,error}=await supabaseClient.from('orders').select('id,order_number,status,payment_method,payment_status,payment_reference,total_bdt,subtotal_bdt,delivery_fee_bdt,delivery_area,delivery_address,created_at,order_items(product_name_en,product_name_bn,sku,package_size_en,package_size_bn,unit_price_bdt,quantity,line_total_bdt)').eq('user_id',session.user.id).order('created_at',{ascending:false});
